fn fibonacci(n: usize) -> Vec<i32> {
    // Problem states n >= 2, but handle small n defensively.
    if n == 0 {
        return Vec::new();
    }
    if n == 1 {
        return vec![0];
    }

    let mut ret = vec![0i32; n];
    ret[0] = 0;
    ret[1] = 1;

    for i in 2..n {
        let a = ret[i - 1] as i64;
        let b = ret[i - 2] as i64;
        let sum = a + b; // safe within i64, and guaranteed to fit into i32 by problem statement
        ret[i] = sum as i32;
    }

    ret
}